test("SOF 16384×16384 4:2:0 without SOS throws before allocating", () => {
  const bytes = Uint8Array.of(
    0xff,
    0xd8,
    0xff,
    0xc0,
    0x00,
    0x11,
    8,
    0x40,
    0x00,
    0x40,
    0x00,
    3,
    1,
    0x22,
    0,
    2,
    0x11,
    0,
    3,
    0x11,
    0,
    0xff,
    0xd9,
  );
  assert.equal(bytes.length, 23);
  assert.throws(() => decodeJpeg(bytes), /JPEG: .*maxPixels/);
});

test("maxPixels counts image pixels, not MCU padding or chroma samples", () => {
  const jpeg = encodeJpeg(createPixelBuffer(9, 9), { quality: 50, chroma: "4:2:0" });
  // 4:2:0 pads 9×9 to 16×16 and adds chroma planes; the budget is still 81 pixels.
  assert.equal(decodeJpeg(jpeg, { maxPixels: 81 }).width, 9);
  assert.throws(() => decodeJpeg(jpeg, { maxPixels: 80 }), /JPEG: 9x9 exceeds maxPixels/);
});

test("1-pixel 4:2:0 JPEG decodes", () => {
  const src = fillPixels(1, 1, () => [200, 10, 30, 255]);
  const jpeg = encodeJpeg(src, { quality: 95, chroma: "4:2:0" });
  const decoded = decodeJpeg(jpeg);
  assert.equal(decoded.width, 1);
  assert.equal(decoded.height, 1);
  assert.equal(decoded.data[3], 255);
  assert.ok(Math.abs((decoded.data[0] ?? 0) - 200) < 40);
});

test("8×8 4:2:0 JPEG decodes with H=2 V=2 sampling", () => {
  const src = fillPixels(8, 8, (x, y) => [x * 30, y * 30, 80, 255]);
  const jpeg = encodeJpeg(src, { quality: 90, chroma: "4:2:0" });
  let i = 0;
  let ySample = 0;
  while (i + 9 < jpeg.length) {
    if (jpeg[i] === 0xff && (jpeg[i + 1] === 0xc0 || jpeg[i + 1] === 0xc2)) {
      ySample = jpeg[i + 11] ?? 0;
      break;
    }
    i += 1;
  }
  assert.equal(ySample, 0x22);
  const decoded = decodeJpeg(jpeg);
  assert.equal(decoded.width, 8);
  assert.equal(decoded.height, 8);
});

function insertDri(jpeg: Uint8Array, interval: number): Uint8Array {
  let i = 2;
  while (i + 1 < jpeg.length) {
    if (jpeg[i] !== 0xff) {
      i += 1;
      continue;
    }
    const m = jpeg[i + 1];
    if (m === 0xda) {
      const dri = new Uint8Array(6);
      dri[0] = 0xff;
      dri[1] = 0xdd;
      dri[2] = 0x00;
      dri[3] = 0x04;
      dri[4] = (interval >> 8) & 0xff;
      dri[5] = interval & 0xff;
      const out = new Uint8Array(jpeg.length + dri.length);
      out.set(jpeg.subarray(0, i), 0);
      out.set(dri, i);
      out.set(jpeg.subarray(i), i + dri.length);
      return out;
    }
    if (m === 0xd8 || m === 0xd9 || (m !== undefined && m >= 0xd0 && m <= 0xd7)) {
      i += 2;
      continue;
    }
    if (m === undefined || m === 0x00 || m === 0xff) {
      i += 1;
      continue;
    }
    const len = ((jpeg[i + 2] ?? 0) << 8) | (jpeg[i + 3] ?? 0);
    i += 2 + len;
  }
  throw new Error("no SOS");
}

test("restart interval 0 and interval covering the whole image still decode", () => {
  const src = fillPixels(8, 8, (x, y) => [x * 20, y * 20, 90, 255]);
  const jpeg = encodeJpeg(src, { quality: 90, chroma: "4:4:4" });
  const plain = decodeJpeg(jpeg);
  const dri0 = decodeJpeg(insertDri(jpeg, 0));
  assert.deepEqual(dri0.data, plain.data);
  const oneMcu = decodeJpeg(insertDri(jpeg, 1));
  assert.deepEqual(oneMcu.data, plain.data);
  const huge = decodeJpeg(insertDri(jpeg, 0xffff));
  assert.deepEqual(huge.data, plain.data);
});

test("libjpeg-turbo restart fixture still decodes with DRI present", () => {
  const decoded = decodeJpeg(fromB64(RESTART_JPEG), { upsample: "nearest" });
  assert.equal(decoded.width, W);
  assert.equal(decoded.height, H);
});

/**
 * Progressive gray SOF2 (all-ones DQT, one 1-bit DC code), one DC-first scan
 * whose data sets every DC to 0, then `refineScans` DC-refinement scans that
 * carry no entropy data at all (~10 bytes each).
 */
function scanBomb(side: number, refineScans: number): Uint8Array {
  const p: number[] = [0xff, 0xd8];
  p.push(0xff, 0xdb, 0x00, 0x43, 0x00, ...Array.from({ length: 64 }, () => 1));
  p.push(0xff, 0xc2, 0x00, 0x0b, 8, side >> 8, side & 255, side >> 8, side & 255, 1, 1, 0x11, 0);
  p.push(0xff, 0xc4, 0x00, 0x14, 0x00, 1, ...Array.from({ length: 15 }, () => 0), 0);
  p.push(0xff, 0xda, 0x00, 0x08, 1, 1, 0x00, 0, 0, 0x00);
  const blocks = Math.ceil(side / 8) ** 2;
  for (let i = 0; i < Math.ceil(blocks / 8); i++) {
    p.push(0);
  }
  for (let s = 0; s < refineScans; s++) {
    p.push(0xff, 0xda, 0x00, 0x08, 1, 1, 0x00, 0, 0, 0x10);
  }
  p.push(0xff, 0xd9);
  return new Uint8Array(p);
}

test("more than 100 scans throws (libjpeg-turbo's fuzzing scan limit)", () => {
  // 101 refinement scans + the DC scan: a few KB that used to cost a full
  // image pass per scan (3000 scans on 4096² took ~29 s in shrinkImage).
  const bomb = scanBomb(1024, 101);
  assert.throws(() => decodeJpeg(bomb), /JPEG: more than 100 scans/);
});

test("a scan with no entropy data stops at the marker instead of walking the image", () => {
  const plain = decodeJpeg(scanBomb(256, 0));
  const t = performance.now();
  const refined = decodeJpeg(scanBomb(256, 99));
  // Generous DoS bound; the pixel check below is the real assertion.
  assert.ok(performance.now() - t < 1000);
  // The old reader fed 1-bits past the marker, so each empty refinement scan
  // set a DC bit in every block. Now the data runs out and nothing changes.
  assert.deepEqual(refined.data, plain.data);
});

test("a JPEG whose scan is cut short and closed with EOI still decodes (gray fill)", () => {
  const img = createPixelBuffer(64, 64);
  for (let i = 0; i < img.data.length; i += 4) {
    img.data[i] = (i >> 4) & 255;
    img.data[i + 1] = 90;
    img.data[i + 2] = 200;
    img.data[i + 3] = 255;
  }
  const full = encodeJpeg(img, { quality: 90 });
  let sos = 2;
  while (!(full[sos] === 0xff && full[sos + 1] === 0xda)) {
    sos += 1;
  }
  const cut = Math.floor((sos + full.length) / 2);
  const truncated = new Uint8Array(cut + 2);
  truncated.set(full.subarray(0, cut));
  truncated[cut - 1] = truncated[cut - 1] === 0xff ? 0 : (truncated[cut - 1] ?? 0);
  truncated[cut] = 0xff;
  truncated[cut + 1] = 0xd9;
  const ref = decodeJpeg(full);
  const out = decodeJpeg(truncated);
  assert.equal(out.width, 64);
  // The first rows were fully coded and match the complete file.
  assert.deepEqual(out.data.subarray(0, 64 * 4 * 8), ref.data.subarray(0, 64 * 4 * 8));
});

test("50 MP 4:2:0 and 24 MP 4:4:4 phone JPEG headers fit the default maxPixels", () => {
  for (const [w, h, hv] of [
    [8160, 6120, 0x22],
    [6000, 4000, 0x11],
  ] as const) {
    const sof = [0xff, 0xd8, 0xff, 0xc0, 0, 17, 8, h >> 8, h & 255, w >> 8, w & 255, 3];
    sof.push(1, hv, 0, 2, 0x11, 1, 3, 0x11, 1);
    // No SOS: the budget check passes, then the decoder reports the missing scan.
    assert.throws(() => decodeJpeg(new Uint8Array([...sof, 0xff, 0xd9])), /JPEG: missing a scan/);
  }
});
